  padding: 20px 30px;
  background-color: green;
  color: white;
}

.menu {
  height: 100px;
  width: 100px;
  background-color: #bd4439;
}
</code></pre>
<p>Here is the codepen link -
<a href="https://codepen.io/raghav-sharma333/pen/eYeZYGO" rel="nofollow noreferrer">https://codepen.io/raghav-sharma333/pen/eYeZYGO</a></p>
