          {% else %}
              &lt;p class=&quot;article-content&quot;&gt;{{&quot;Bridge : &quot; + post.bridge + &quot;\nColor : &quot; + post.color + &quot;\nFrets : &quot; + post.frets}}&lt;/p&gt;
          {% endif %}
        &lt;/div&gt;
