    margin: 0;
    padding: 0;
  }

.header
{
    background-color: #000000;
    margin: 0;
    padding: 0;
}

.header a
{
    margin-left: 2rem;
}

.footer
{
    background-color: #000000;
    color: #ffffff;
    height: 100%;
