  url = $("input")[0].value;
  img = $("input")[1].value;

  if (!url.length) {
    return alert('Please enter URL');
  }

}

let send = _ =&gt; {

  $.ajax({
    type: "POST",
    url: url,
    async: true,
    data: {
      file: (img)
    },
  });
}</code></pre>
