            tableHtml += &quot;&lt;tbody&gt;&lt;tr&gt;&quot;;
            for (var i = 0; i &lt; o.length; i++) {
                for (var j = 0; j &lt; cols.length; j++) {
                    tableHtml += &quot;&lt;td&gt;&quot; + o[i][cols[j]] + &quot;&lt;/td&gt;&quot;;
                }
