<pre><code>export class HeroDetailComponent implements OnInit {
  public heroes: Hero[];
  public powers: Power[];
  submitted = false;
  private hero: Hero;

  constructor(
    private route: ActivatedRoute,
    private heroService: HeroService,
    private powerService: PowerService,
    private location: Location,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getHero();
    this.router.routeReuseStrategy.shouldReuseRoute = () =&gt; false;
    this.getHeroes();
    this.getPowers();
  }

  getHero(): void{
    const id = +this.route.snapshot.paramMap.get('id');
    this.heroService.getHero(id).subscribe(
      (hero: Hero) =&gt; {
        this.hero = hero;
        if (hero.power != null) {
          this.powerService.getPowerById(hero.power).subscribe(
            (powerResponse) =&gt; {
              hero.power = powerResponse;
            }
          );
        }
      });
  }
  public getHeroes(): void {
    this.heroService.getHeroes().subscribe(
      (response: Hero[]) =&gt; {
        this.hero = response;
        },
      (error: HttpErrorResponse) =&gt; {
        alert(error.message);
      }
    );
  }

  public getPowers(): void {
    this.powerService.getAllPowers().subscribe(
      (response: Power[]) =&gt; {
        this.power = response;
      },
      (error: HttpErrorResponse) =&gt; {
        alert(error.message);
      }
    );
  }

  goBack(): void {
    this.location.back();
  }

  save(): void {
    this.heroService.updateHero(this.hero, this.hero.id)
      .subscribe(() =&gt; this.goBack());
  }
  onSubmit() {this.submitted = true;}

  get diagnostic() {return JSON.stringify(this.hero);}

</code></pre>,"<p>Is obvious why it'll disappear, look at your template again:</p>

