  if (action.type === REDUCER_ACTIONS.input){
    return {...state, value: action.value}
  }

  if (action.type === REDUCER_ACTIONS.blur){
     return {...state, pristine: false}
   }

  return INITAL_STATE;
 }

const useForm = () =&gt; {
   const [inputState, dispatch] = useReducer(reducer,INITAL_STATE)

