}

hashtableEntry* createTableEntry(char* newKey) {
     hashtableEntry* e = (hashtableEntry*) malloc (sizeof(hashtableEntry));
     e-&gt;hashKey = newKey;
     return e;
}

void initHashTable(hashTable* ht) {
