  background-size: contain;
  margin-right: 10px !important;
}

.btn {
  display: inline-flex;
  -webkit-box-align: center;
  align-items: center;
  -webkit-box-pack: center;
  justify-content: center;
  position: relative;
  width: 57px;
  height: 44px;
  font-size: 16px;
  line-height: 1.5;
  font-family: 'Open Sans', sans-serif;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: 4px;
  transition-duration: 450ms;
  transition-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
  word-break: normal;
  color: rgba(0, 0, 0, 0.54);
  background: rgb(255, 255, 255);
  box-shadow: rgb(0 0 0 / 12%) 0px 2px 4px 0px, rgb(0 0 0 / 12%) 0px 0px 4px 0px;
  white-space: nowrap;
  border-style: none;
  border-width: 0px;
  border-color: rgb(255, 255, 255);
  margin: 0px;
  cursor: pointer;
}

.btn:hover {
  background-color: #F5F5F5;
  box-shadow: 1px 1px 3px 3px #E0E0E0;
}

.swap-rate-container .btn-arrows {
  transform: rotate(90deg);
  opacity: 0.54;
  transition: opacity 450ms cubic-bezier(0.23, 1, 0.32, 1);
  position: absolute;
  z-index: 0;
  font-family: 'Open Sans', sans-serif;
}

.currency {
  padding: 40px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

input::placeholder {
  font-family: 'Open Sans', sans-serif;
  font-size: 16px;
}

.currency input {
  background: transparent;
  font-size: 16px;
  line-height: 1.5;
  text-align: right;
  font-weight: 400;
  color: rgba(0, 0, 0, 0.87);
  border-style: none;
  border-width: 0px;
  border-radius: 0px;
  background: transparent;
  box-shadow: none;
  outline: none;
  width: 65%;
  font-family: 'Open Sans', sans-serif;
  background: transparent;
  border-bottom: 2px solid rgba(0, 0, 0, 0.12);
  margin-left: 15px
}

.currency input:hover {
  display: block;
  line-height: 1.5;
  font-family: "Open Sans", sans-serif;
  border-bottom: 2px solid rgba(0, 0, 0, 0.54);
}

.currency input:focus {
  border-bottom: 2px solid #8dc641;
  border-bottom-color: transparent;
}

.select-placeholder {
  background: rgb(255, 255, 255);
  color: rgba(0, 0, 0, 0.38);
}

.swap-rate-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.rate {
  color: black;
  font-size: 15px;
  padding: 0 10px;
  background: #E0E0E0;
  line-height: var(--tl-small);
  padding: 8px;
  font-family: 'Open Sans', sans-serif;
  border-radius: 2px;
}

input::-webkit-inner-spin-button {
  display: none !important;
}

.input-container {
  position: relative;
  width: 65%;
  margin-left: 15px;
  bottom: -1px;
}

.input-container input {
  width: 100%;
  margin-left: 0;
}

.input-container input:focus {
  border-bottom: 2px solid #8dc641;
}

.input-box:hover + .input-border {
  transform: scaleX(1);
}

.input-border {
  display: block;
  border-bottom: 2px solid rgba(0, 0, 0, 0.54); 
  transform: scaleX(0);
  transition: transform 250ms ease-in-out;
  position: absolute; bottom: 0; left: 0;
  width: 102%;
}

@media (maz-width: 600px) {
  .currency input {
    width: 200px;
  }
}

.display-none {
  display: none;
}



