<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>var canvas = document.getElementById("canvas"),
    context = canvas.getContext("2d"),
    centerX = canvas.width / 2,
    centerY = canvas.height / 2,
    rad = (Math.PI * 2) / 50,
    speed = 1;
function blueCircle(speed) {
    context.save();
    context.beginPath();
    context.strokeStyle = "#ffffff";
    context.lineWidth = 4;
    context.arc(
        centerX,
        centerY,
        40,
        -Math.PI / 2,
        -Math.PI / 2 + speed * rad,
        false
    );
    context.stroke();
    context.restore();
}
function reblueCircle(speed) {
    context.save();
    context.beginPath();
    context.strokeStyle = "#ffffff69";
    context.lineWidth = 4;
    context.arc(
        centerX,
        centerY,
        40,
        -Math.PI / 2,
        -Math.PI / 2 + speed * rad,
        false
    );
    context.stroke();
    context.restore();
}
function whiteCircle() {
    context.save();
    context.beginPath();
    context.strokeStyle = "#ffffff69";
    context.lineWidth = 4;
    context.arc(centerX, centerY, 40, 0, Math.PI * 2, false);
    context.stroke();
    context.closePath();
    context.restore();
}
var res = false;
(function drawFrame() {
    window.requestAnimationFrame(drawFrame, canvas);
    context.clearRect(0, 0, canvas.width, canvas.height);
    whiteCircle();
    blueCircle(speed);
    if (res) {
        speed -= 0.1;
        reblueCircle(speed);
    }
    if (speed &gt; 50 &amp;&amp; !res) {
        res = true;
    } else if (speed &lt; 50 &amp;&amp; !res) {
        speed += 0.1;
    } else if (speed &gt; 50 &amp;&amp; !res) {
        res = true;
    }
})();</code></pre>
