    ctx.arc(colorPoints[i].x, colorPoints[i].y, colorPoints[i].radius, 0 * radian, 360 * radian, false);
                context.closePath( );
                ctx.fill();
    currentFrame = currentFrame + 1;
}
}
}

var animate = function(){
