    photo: 'https://slova.de/raspasy/images/male_sad.png'
  }).css({
    position: 'absolute',
    right: '30px',
    top: '20px'
  });
});
</code></pre>,<p>You need to add <code>position: relative</code> for <code>#gameTd</code> for positioning relative to this block.</p>,css

