    -moz-user-select: none;
    user-select: none;
  }

  @media (min-width: 768px) {
    .bd-placeholder-img-lg {
      font-size: 3.5rem;
    }
  }
.thumbcard{
width: 15rem;
height: 18rem;
}

@media(max-width: 768px){
.thumbcard{
width: 10rem;
height: 18rem;
}
}

a.custom-card,
a.custom-card:hover {
color: inherit;
text-decoration: none;
}
@media(max-width: 768px){
a.custom-card h5{
font-size: 1rem;
}
a.custom-card .card-body{
padding: 0.5rem 0.5rem;
font-size: 0.95rem;
line-height: none;
}
}</code></pre>
