<pre class="snippet-code-css lang-css prettyprint-override"><code>/*
 *
 * CSS written based on SMACSS architecture.
 * To learn more, visit: http://smacss.com/
 * 
 * For simplicity, no reset or normalize is added. 
 * To learn more, visit: https://css-tricks.com/reboot-resets-reasoning/
 *
*/



@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@300&amp;display=swap');

/* ---- Base Rules ---- */



*{
    padding: 0;
    margin: 0;
    box-sizing: border-box;
}

html{
    font-family: 'Roboto', sans-serif;
    scroll-behavior: smooth;
}



body {
    margin: 0;
    background: linear-gradient(to bottom, #c31432, #240b36);
    color: #fff;
}

ul {
    margin: 0;
    padding: 0;
    overflow: hidden;
    background: linear-gradient(to right top, #abbaab, #a34444);
}


section {
    position: relative;
    min-height: 100vh;
    width: 100%;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
}

img {
    max-width: 100%;
}

button {
    cursor: pointer;
    border-radius: 12.5px;
}

/* Typeography General*/

header {
    position: absolute;
    top: 5px;
    bottom: 5px;
    align-items: center;
    text-align: center;
    background: transparent;
    text-decoration: blanchedalmond;
    text-shadow: black;
}

h1 {
    font-family: 'Fira Sans', sans-serif;
    border-radius: 50%;
    border-color: black;
    text-align: center;
    align-items: center;
    color: goldenrod;
    background: linear-gradient(to right top, #8e0e00, #1f1c18);
}

.main__hero {
    font-family: 'Fira Sans', sans-serif;
    font-size: large;
    top: 85px;
    float: middle;
    align-items: center;
    border-color: black;
    text-align: center;
    color: black;
    position: sticky;
}

@media only screen and (min-width: 35em) {
    h1 {
        font-size: large;
        text-align: center;
        align-items: center;
        color: goldenrod;
    }
}

h2 {
    border-bottom: 1px solid #cc1;
    font-family: 'Oxygen', Sans-Serif;
    font-size: 1.2em;
    color: azure;
}

p {
    line-height: 1.5em;
    font-size: 0.9em;
    color: #eee;
    word-spacing: 0.1em;
}

/* ---- Layout Rules ---- */

main {
    margin: 10vh 1em 10vh;
}

.main-hero {
    min-height: 40vh;
    padding-top: 3em;
}


/* Some sections features*/

section h2 {
    display: sticky;
    font-size: 7.7vh;
    top: 10px;
    bottom: 7px;
    text-shadow: black;
    color: cornsilk;
}

section h3 {
    display: flex;
    font-size: 2.0rem;
    top: 10px;
    bottom: 7px;
    text-shadow: black;
    color: burlywood;
}

/* ---- Module Rules ---- */


/* Return Top Button*/

.topbtnclass {
    padding: 15px;
    bottom: 20px;
    right: 10px;
    position: fixed;
    text-align: center;
    border-radius: 15px;
    outline: none;
    color: white;
    z-index: 99;
    font-size: 12.5px;
    cursor: pointer;
    align-items: center;
    background: linear-gradient(to right bottom, #304352, #d7d2cc);
    font-family: 'Oxygen', Sans-Serif;
}

/* Return Top Button Hover */

.topbtnclass:hover {
    color: goldenrod;
    display: flex;
    background: linear-gradient(to right bottom, #870000, #190a05);
}

/* Adding an active class */

.active, .a:hover {
    background: linear-gradient(to right bottom, #852121, #190a05);
    color: goldenrod;
    border-radius: 50%;
}

/* Navigation Styles*/

.navbar__menu {
    position: fixed;
    top: 0px;
    float: middle;
    background: linear-gradient(to right bottom, #304352, #d7d2cc);
    width: 100%;
    max-width: 2150px;
    margin:0 auto;
    text-align: center;
    padding: 10px;

}
.navbar__menu ul {
    position: relative;
    padding-left: 1px;
    padding-right: 1px;
    text-align: center;
    display: inline-block;
    background: linear-gradient(to right bottom, #304352, #d7d2cc);
    border-radius: 90%;

}

.navbar__menu li {
    display: inline-block;
    position: relative;

}


.navbar__menu li ul a {
    display: inline-block;
    padding: 7px 14px;
    text-decoration: none;
}

.navbar__menu li ul.active{
    background: linear-gradient(to right bottom, #c31432, #240b36);
    color: goldenrod;
}



.navbar__menu .menu__link {
    display: flex;
    padding: 1em;
    font-weight: bold;
    text-decoration: none;
    text-shadow: black;
    color: goldenrod;
    border-radius: 50%;
}

.navbar__menu .menu__link:hover {
    color: wheat;
    transition: ease 0.3s all;
}




/* Header Styles */

.page__header {
    background: linear-gradient(to right bottom, #c31432, #240b36);
    position: sticky;
    font-size: 2vw;
    width: 100%;
    z-index: 50;
    border-color: black;
}

/* Footer Styles */

.page__footer {
    background: #000;
    padding: 3em;
    color: #fff;
}

.page__footer p {
    color: #fff;
}

/* ---- Theme Rules ---- */

/* Landing Container Styles */

.landing__container {
    padding: 1em;
    text-align: center;
    align-items: center;
}

@media only screen and (min-width: 35em) {
    .landing__container {
        max-width: 50em;
        padding: 4em;
    }
}

section:nth-of-type(even) .landing__container {
    text-align: center;
    align-items: center;
}

/* Background Circles */

/* Note that background circles are created with psuedo elements before and after */

/* Circles appear to be random do to use of :nth-of-type psuedo class */

section:nth-of-type(odd) .landing__container::before {
    content: '';
    background: rgba(255, 255, 255, 0.187);
    position: fixed;
    z-index: -5;
    width: 50vh;
    height: 50vh;
    border-radius: 50%;
    opacity: 0;
    transition: ease 0.5s all;
}

section:nth-of-type(even) .landing__container::before {
    content: '';
    background: rgb(255, 255, 255);
    background: linear-gradient(0deg, rgba(255, 255, 255, .1) 0%, rgba(255, 255, 255, .2) 100%);
    position: fixed;
    top: 3em;
    right: 3em;
    z-index: -5;
    width: 40vh;
    height: 40vh;
    border-radius: 50%;
    opacity: 0;
    transition: ease 0.5s all;
}

section:nth-of-type(3n) .landing__container::after {
    content: '';
    background: rgb(255, 255, 255);
    position: absolute;
    right: 0;
    bottom: 0;
    z-index: -5;
    width: 10vh;
    height: 10vh;
    border-radius: 50%;
    opacity: 0;
    transition: ease 0.5s all;
}

section:nth-of-type(3n + 1) .landing__container::after {
    content: '';
    background: rgb(255, 255, 255);
    position: absolute;
    right: 20vw;
    bottom: -5em;
    z-index: -5;
    width: 15vh;
    height: 15vh;
    border-radius: 50%;
    opacity: 0;
    transition: ease 0.5s all;
}

/* ---- Theme State Rules ---- */

/* Section Active Styles */

/* Note: your-active-class class is applied through javascript. You should update the class here and in the index.html to what you set in your javascript file.  */

section.active {
    color: goldenrod;
    background: linear-gradient(to right bottom, #870000, #190a05);
}

section.active .landing__container::before {
    opacity: 1;
    animation: rotate 4s linear 0s infinite forwards;
}

section.active .landing__container::after {
    opacity: 1;
    animation: rotate 5s linear 0s infinite forwards reverse;
}

/* Section Active Styles Keyframe Animations */

@keyframes rotate {
    from {
        transform: rotate(0deg) translate(-1em) rotate(0deg);
    }
    to {
        transform: rotate(360deg) translate(-1em) rotate(-360deg);
    }
}

/* Active Class */

li a.active {
    color: goldenrod;
}

.active {
    color: goldenrod;
    background: linear-gradient(to right bottom, #870000, #190a05);
    cursor: pointer;
    position: relative;
}

.active:hover {
    color: goldenrod;
    background: linear-gradient(to right bottom, #870000, #190a05);
    position: relative;
}

/*Page sections Gradients by id*/
#section1 {
    /*border-radiuse at 25% to makesections more rounded*/
    border-radius: 25%;
    background-color: #fdb813;
    background-image: linear-gradient(315deg, #fdb813 0%, #788cb6 74%);
}


#section2 {
    border-radius: 25%;
