 top: -8px;
 left: -8px;
 right: -8px;
 bottom: -8px;
 content: " ";
 position: absolute;
 border: 1px solid #dedede;
 border-radius: 50% !important;
}

.business-post-link:hover i,
.business-post-link:hover i:after {
 transition: all 0.3s ease-in-out;
}

.business-post-link:hover i {
 background: #db9e33;
}

.business-post-link:hover i:after {
 border-color: #db9e33;
}

.rounded-x {
    border-radius: 50% !important;
}

.business-post-title {
 font-size: 20px;
 line-height: 24px;
 color: #555;
}


