<p>Edit: Sorry I guess I should have mentioned this, but this is an animated progress bar, not a static image. So combining them into one png is not an answer, I need to dynamically position the circular div behind the transparency of the logo png so it can function as a progress bar.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const pieCharts = document.querySelectorAll('[data-percentage]');

if (pieCharts) {
  for (let i = 0; i &lt; pieCharts.length; i += 1) {
    const slice = pieCharts[i];
    const percentage = slice.getAttribute('data-percentage');
    const circumference = 31.4;
    const strokeDash = Math.round((percentage * circumference) / 100);
    const strokeDashArray = `${strokeDash} ${circumference}`;

    slice.setAttribute('stroke-dasharray', strokeDashArray);
  }
}</code></pre>
